SELECT
    id, cell, browse_date, application_name, return_result1, created_by, created_time,
       last_modified_by, last_modified_time, last_modified_user_id, last_modified_user_name
FROM b_dd_data_taikang_record
WHERE
    id > #{searchId}
    AND created_time >= #{previousTime}
    AND created_time < #{nowTime}
ORDER BY id ASC
LIMIT #{searchSize}
